let revealed=mut.@($bool);lp(let i=0;i<n;i=i+1){revealed=revealed+@(false)};
let lives=mut.6;
lp(let g=0;g<gparts.len();g=g+1){let letter=s.trim(gparts.get(g));if(s.len(letter)>0){let hit=mut.false;lp(let i=0;i<n;i=i+1){if(s.equals(ch(word;i);letter)){revealed=revealed.set(i;true);hit=true}};if(!(hit)){lives=lives-1}}};
let masked=mut."";lp(let i=0;i<n;i=i+1){if(revealed.get(i)){masked=s.concat(masked;ch(word;i))}el{masked=s.concat(masked;"_")}};
io.println(masked);io.println(s.fromint(lives));<0}

